extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var quiz := await instantiate_scene("res://quiz.tscn")
	if not check("quiz_exists", quiz != null, "La scena quiz.tscn deve caricarsi correttamente"):
		return

	var buttons: Array = get_prop(quiz, "answer_buttons", [])
	if not check("buttons_exist", buttons.size() >= 2, "L'array answer_buttons deve contenere i pulsanti"):
		return

	var b0: Button = buttons[0]
	# Premi la prima risposta (corretta per la domanda di default)
	click_button(b0)
	await wait_frames(2)

	var correct_color := Color(0.2, 0.8, 0.2)
	check("color_changed", b0.self_modulate == correct_color or b0.self_modulate != Color.WHITE, "Dopo la risposta corretta il pulsante deve cambiare self_modulate")

